"""Serving-side index: store location, metadata stamp, and artifact ingest.

The copilot serves precomputed vectors: :func:`ingest_vector_artifact` loads a
parquet artifact (built off the serving path) into a :class:`BaseVectorStore` —
no embedding here. The store lives at a directory keyed by
``(embed_engine, embed_model)`` *only* — not the corpus version, which rebuilds
in place — and the corpus version + embedding config are stamped into
``meta.json``.
"""

import hashlib
import json
from pathlib import Path
from typing import Any, Dict, Optional

import structlog

from rasa.builder.document_retrieval.local.config import (
    LocalRetrievalConfig,
    SearchMode,
)
from rasa.builder.document_retrieval.local.embedding import Embedder
from rasa.builder.document_retrieval.local.lancedb_store import LanceDBVectorStore
from rasa.builder.document_retrieval.local.parquet_artifact import read_vectors_parquet
from rasa.builder.document_retrieval.local.vector_store import BaseVectorStore

structlogger = structlog.get_logger()

_META_FILENAME = "meta.json"


class IndexConfigMismatch(ValueError):
    """Raised when an existing index was built with incompatible config."""


def _index_key(cfg: LocalRetrievalConfig) -> str:
    """Stable short hash over the fields that define the index's vector space.

    Excludes the corpus version: a corpus change rebuilds in place, not into a
    separate index directory. Chunking is code-defined, so it is not part of the key.
    """
    payload = {
        "embed_engine": cfg.embedder.embed_engine,
        "embed_model": cfg.embedder.embed_model,
    }
    canonical = json.dumps(payload, sort_keys=True)
    return hashlib.sha1(canonical.encode("utf-8")).hexdigest()[:16]


def _table_dir(cfg: LocalRetrievalConfig) -> Path:
    """On-disk location for this config's index (and its meta.json)."""
    return Path(cfg.index_cache_dir) / _index_key(cfg)


def build_vector_store(cfg: LocalRetrievalConfig) -> BaseVectorStore:
    """Construct the configured vector store at this config's index location."""
    location = str(_table_dir(cfg))
    if cfg.vector_store == "lancedb":
        return LanceDBVectorStore(location)
    raise ValueError(f"Unknown vector_store: {cfg.vector_store}")


def _meta_path(table_dir: Path) -> Path:
    return table_dir / _META_FILENAME


def _write_meta(
    table_dir: Path,
    cfg: LocalRetrievalConfig,
    embed_dim: int,
    corpus_version: str,
    document_count: int,
    chunk_count: int,
) -> None:
    """Stamp what this index represents (audit + consistency check)."""
    table_dir.mkdir(parents=True, exist_ok=True)
    _meta_path(table_dir).write_text(
        json.dumps(
            {
                "embed_engine": cfg.embedder.embed_engine,
                "embed_model": cfg.embedder.embed_model,
                "embed_dim": embed_dim,
                "corpus_version": corpus_version,
                "document_count": document_count,
                "chunk_count": chunk_count,
            },
            indent=2,
        )
    )


def _assert_artifact_matches(
    cfg: LocalRetrievalConfig, embed_dim: int, meta: Dict[str, Any]
) -> None:
    """Refuse to ingest an artifact the serving side cannot query against.

    Enforces the embedding-model parity invariant (engine/model/dim).
    """
    expected = {
        "embed_engine": cfg.embedder.embed_engine,
        "embed_model": cfg.embedder.embed_model,
        "embed_dim": embed_dim,
    }
    mismatches = {k: (meta.get(k), v) for k, v in expected.items() if meta.get(k) != v}
    if mismatches:
        raise IndexConfigMismatch(
            "Vector artifact was built with config the serving backend cannot "
            f"query against (field: (artifact, serving)) {mismatches}. Rebuild "
            "the artifact or align the serving config."
        )


def _stamped_corpus_version(table_dir: Path) -> Optional[str]:
    """Corpus version recorded in the index's meta.json, if any."""
    meta_path = _meta_path(table_dir)
    if not meta_path.exists():
        return None
    return json.loads(meta_path.read_text()).get("corpus_version")


def ingest_vector_artifact(
    store: BaseVectorStore,
    cfg: LocalRetrievalConfig,
    parquet_path: str,
    embedder: Embedder,
) -> None:
    """Load precomputed vectors from a parquet artifact into ``store``.

    Args:
        store: The vector store to populate.
        cfg: Local retrieval configuration (for parity assertion + meta stamp).
        parquet_path: Path to the prebuilt parquet vector artifact.
        embedder: Query-time embedder; only its ``dim`` is used here (parity).
    """
    rows, meta = read_vectors_parquet(Path(parquet_path))
    _assert_artifact_matches(cfg, embedder.dim, meta)

    key = _index_key(cfg)
    table_dir = _table_dir(cfg)
    corpus_version = str(meta.get("corpus_version", ""))

    if store.exists() and _stamped_corpus_version(table_dir) == corpus_version:
        structlogger.info(
            "vector_artifact.ingest_noop", key=key, corpus_version=corpus_version
        )
        return

    if store.exists():
        store.drop()
    store.add(rows)
    # FTS index backs hybrid search only; skip the build cost when serving vector.
    if cfg.search_mode is SearchMode.HYBRID:
        store.ensure_text_index()
    _write_meta(
        table_dir,
        cfg,
        embedder.dim,
        corpus_version,
        int(meta.get("document_count", 0)),
        len(rows),
    )

    structlogger.info(
        "vector_artifact.ingested",
        key=key,
        corpus_version=corpus_version,
        chunk_count=len(rows),
        embed_dim=embedder.dim,
    )
